import{_ as n,o as t,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Announcements — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Announcements — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/announcements"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Announcements — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/announcements"}]]},"headers":[],"relativePath":"user-guide/announcements.md","filePath":"user-guide/announcements.md","lastUpdated":1786147061000}'),r={name:"user-guide/announcements.md"};function s(i,e,d,c,l,m){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="announcements-—-user-guide" tabindex="-1">Announcements — User Guide <a class="header-anchor" href="#announcements-—-user-guide" aria-label="Permalink to &quot;Announcements — User Guide&quot;">​</a></h1><p>Install <strong>Announcements</strong> from Marketplace (free Communication module). Until it is installed, announcements nav, dialog, and dashboard block stay hidden.</p><h2 id="who-can-see-announcements" tabindex="-1">Who can see announcements? <a class="header-anchor" href="#who-can-see-announcements" aria-label="Permalink to &quot;Who can see announcements?&quot;">​</a></h2><p>Anyone who can sign in to the workspace — owners, admins, agents, and employees with a User login. There is no separate “view announcements” permission.</p><p>Employees without a linked login cannot open EloSync, so they cannot receive announcements.</p><h2 id="after-login" tabindex="-1">After login <a class="header-anchor" href="#after-login" aria-label="Permalink to &quot;After login&quot;">​</a></h2><p>When there are unread published announcements, a dialog opens after you land in the app. Choose <strong>Mark as read</strong> (records time + IP) or <strong>View all</strong>. Closing without marking as read does not clear the dialog for the next visit.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>On the workspace dashboard, an <strong>Announcements</strong> section appears under the welcome greeting only while you still have unread published announcements. Each item is labeled <strong>Announcement</strong> and includes <strong>Mark as read</strong>. After you mark them as read, the section hides. Use <strong>Announcements</strong> in the nav (or View all) for full history.</p><h2 id="announcements-page" tabindex="-1">Announcements page <a class="header-anchor" href="#announcements-page" aria-label="Permalink to &quot;Announcements page&quot;">​</a></h2><p>Open <strong>Announcements</strong> from the sidebar.</p><ul><li>Everyone sees published (non-expired) history.</li><li>Users with create/update/delete/restore/force-delete permissions can manage drafts, trash, and permanent delete.</li><li>Open an announcement to read it and mark it as read again (updates last read time/IP).</li><li>Users with <strong>view who read</strong> (<code>announcements.view_reads</code>) see the readers list with first/last read time and IP.</li></ul><h2 id="creating-announcements" tabindex="-1">Creating announcements <a class="header-anchor" href="#creating-announcements" aria-label="Permalink to &quot;Creating announcements&quot;">​</a></h2><p>Requires <code>announcements.create</code>.</p><ol><li>Click <strong>New announcement</strong></li><li>Enter title and body</li><li>Set status to <strong>Draft</strong>, <strong>Published</strong>, or <strong>Archived</strong></li><li>Optional expires-at (workspace timezone for display; stored as UTC)</li></ol><p>Publishing notifies other workspace users in the notification center.</p><h2 id="permissions-mutations-only" tabindex="-1">Permissions (mutations only) <a class="header-anchor" href="#permissions-mutations-only" aria-label="Permalink to &quot;Permissions (mutations only)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Ability</th></tr></thead><tbody><tr><td><code>announcements.create</code></td><td>Create announcements</td></tr><tr><td><code>announcements.update</code></td><td>Edit / publish / archive</td></tr><tr><td><code>announcements.delete</code></td><td>Soft delete</td></tr><tr><td><code>announcements.restore</code></td><td>Restore from trash</td></tr><tr><td><code>announcements.force.delete</code></td><td>Permanently delete</td></tr><tr><td><code>announcements.view_reads</code></td><td>See who read an announcement</td></tr></tbody></table><p>Default role map grants these to <strong>admin</strong>. Workspace owners (<code>superadmin</code>) receive all permissions via provisioning.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/announcements-overview">Announcements overview</a></li><li><a href="/api/tenant-v1-announcements">Tenant API</a></li><li><a href="/user-guide/tenant-application#marketplace-add--remove-modules">Marketplace</a></li></ul>',21)])])}const p=n(r,[["render",s]]);export{h as __pageData,p as default};
